<script>(function(){const f=document.getElementById('bibliographyForm'),t=document.getElementById('tipe_item');function toggle(){document.getElementById('journalFields').style.display=t.value==='jurnal'?'flex':'none'}t.addEventListener('change',toggle);toggle();f.addEventListener('submit',async e=>{e.preventDefault();const b=f.querySelector('button[type=submit]');b.disabled=true;const fd=new FormData(f);fd.append('csrf_token',window.KANDAGA_CSRF||'');try{const r=await fetch('actions/proses-bibliografi.php',{method:'POST',body:fd,headers:{'X-CSRF-Token':window.KANDAGA_CSRF||''}}),d=await r.json();if(!d.success)throw new Error(d.message);window.location.href=d.redirect||'index.php?page=daftar-pustaka'}catch(x){alert(x.message||'Penyimpanan gagal');b.disabled=false}})})();</script>
